import test from 'node:test';import assert from 'node:assert/strict';import {refreshMarket} from '../src/market.mjs';import {CATALOG,DAY} from '../src/engine.mjs';
const now=Date.parse('2026-10-31T12:00Z');
test('failed market requests never invent prices or refresh stale timestamps',async()=>{const original=global.fetch;global.fetch=async()=>{throw Error('network unavailable')};try{const p={eur:100,at:now-6*DAY,fetchedAt:now-6*DAY},m=await refreshMarket({prices:{AAPL:p},events:[]},now);assert.deepEqual(m.prices.AAPL,p);assert.equal(Object.keys(m.prices).length,1);assert.ok(m.errors.length>=25)}finally{global.fetch=original}});
test('provider responses validate symbol, closed observations, FX and rate before storing',async()=>{const original=global.fetch;global.fetch=async url=>{if(url.includes('eurofxref'))return new Response('<Cube time="2026-10-30"><Cube currency="USD" rate="1.1"/><Cube currency="KRW" rate="1500"/></Cube>');if(url.includes('data-api'))return new Response('TIME_PERIOD,OBS_VALUE\n2026-10-30,2.4');if(url.includes('coinbase'))return Response.json({data:{amount:'70000',currency:'EUR'}});const symbol=url.split('/chart/')[1].split('?')[0];return Response.json({chart:{result:[{meta:{symbol:symbol==='MSFT'?'WRONG':symbol,currency:'USD',currentTradingPeriod:{regular:{start:100,end:23500}}},timestamp:[(now-DAY)/1000-23400,(now+DAY)/1000],indicators:{quote:[{close:[110,999]}]}}]}})};try{const m=await refreshMarket({prices:{},events:[]},now);assert.ok(Math.abs(m.prices.AAPL.eur-100)<1e-9);assert.equal(m.prices.AAPL.at,now-DAY);assert.equal(m.prices.MSFT,undefined);assert.equal(Object.keys(m.prices).length,CATALOG.length-1);assert.equal(m.rate.annualPct,2.4);assert.ok(m.errors.some(x=>x.includes('Símbolo')))}finally{global.fetch=original}});
